// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    Receiver receiver;

    function setUp() public {
        c = new Reentrance();
        receiver = new Receiver();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        address actor = address(receiver);
        vm.assume(actor != address(c));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        assertEq(c.getBalance(actor), amount);

        vm.prank(actor);
        c.withdrawBalance();

        // General rule: after withdrawBalance, the recorded balance has been paid
        // out in full, so the contract holds no ether from this user.
        assertTrue(address(c).balance == 0 && c.getBalance(actor) == 0);
    }
}

// Minimal adversarial counterparty: a payable recipient that accepts ether
// (so the low-level call in withdrawBalance succeeds), used as msg.sender.
contract Receiver {
    receive() external payable {}
}
